from py_serverless_kit import Response

ITEMS = [("Espresso", 2.2), ("Cappuccino", 3.1)]


def menu(event, ctx):
    rows = "".join(f"<li>{name}: {price:.2f} EUR</li>" for name, price in ITEMS)
    return Response.html(f"<html><body><h1>Menu</h1><ul>{rows}</ul></body></html>")
"}

